import React, { useState, useEffect } from "react";

export default function NgoDashboard({ token, msg, setMsg, events, setEvents, ngoPanel }) {
  const [newEvent, setNewEvent] = useState({
    title: "",
    description: "",
    location: "",
    date: "",
    requiredVolunteers: 0
  });

  const [volunteers, setVolunteers] = useState(null);
  const [donations, setDonations] = useState(null);
  const [achievements, setAchievements] = useState(null);
  const [selectedParticipants, setSelectedParticipants] = useState(null);

  // ⭐ ADDED: Logged-in NGO details
  const [ngoInfo, setNgoInfo] = useState(null);

  // ⭐ FIXED: Fetch logged-in NGO info
  useEffect(() => {
    if (!token) return;

    (async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/info",
          { headers: { Authorization: `Bearer ${token}` } }
        );

        if (!res.ok) {
          console.error("Failed to fetch NGO info:", res.status, res.statusText);
          return;
        }

        const d = await res.json();

        // only pick name, email, role, totalEvents
        setNgoInfo({
          name: d.name || "N/A",
          email: d.email || "N/A",
          role: d.role || "NGO",
          totalEvents: d.totalEvents || 0
        });

      } catch (e) {
        console.error("Error fetching NGO info:", e);
      }
    })();
  }, [token]);

  function createEvent(e) {
    e.preventDefault();

    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/create-event", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`
      },
      body: JSON.stringify(newEvent)
    })
      .then(r => r.json())
      .then(d => {
        setMsg(d.msg);
        if (d.event) setEvents([...events, d.event]);
      });
  }

  useEffect(() => {
    if (!token) return;
    (async () => {
      try {
        const res = await fetch(
          (process.env.REACT_APP_API || "http://localhost:4000") + "/api/ngo/achievements",
          { headers: { Authorization: `Bearer ${token}` } }
        );
        const d = await res.json();
        setAchievements(d);
      } catch (e) {}
    })();
  }, [token]);

  return (
    <div className="panel">
      {/* PROFILE SECTION */}
      <div style={{ textAlign: "center", marginBottom: 20 }}>
        <img
          src="https://cdn-icons-png.flaticon.com/512/149/149071.png"
          alt="profile"
          style={{
            width: 90,
            height: 90,
            borderRadius: "50%",
            border: "2px solid #ccc",
            marginBottom: 10
          }}
        />

        {ngoInfo ? (
          <>
            <h2 style={{ margin: 4 }}>{ngoInfo.name}</h2>
            <p style={{ margin: 2 }}>{ngoInfo.email}</p>
            <p style={{ margin: 2 }}>Role: {ngoInfo.role}</p>
            <div style={{ marginTop: 10 }}>
              <strong>{ngoInfo.totalEvents}</strong> Events Created
            </div>
          </>
        ) : (
          <p>Loading NGO Info...</p>
        )}
      </div>

      {/* ---------------------- Rest of your code remains unchanged ---------------------- */}
      {/* ...Your create event form, buttons, lists, achievements, etc. */}
    </div>
  );
}
